using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

namespace Nino.Generator.Generation.Emit;

/// <summary>
/// What every generated file shares: its header, the layout of a file of the <c>NinoGen</c> namespace
/// (<see cref="File"/>), and the aliases the files declare for the names their lines repeat.
/// </summary>
internal static class GeneratedCode
{
    /// <summary>The first lines of every generated file.</summary>
    public const string Header = "// <auto-generated/>\n#nullable disable\n#pragma warning disable\n\n";

    /// <summary>The alias of <c>NinoDirect</c> (<c>__NinoDirect</c>), which the interceptors call.</summary>
    public const string DirectAlias = "using __NinoDirect = " + TypeNames.CoreCompilerServices + "NinoDirect;";

    /// <summary>The alias of <c>InterceptsLocationAttribute</c> (<c>__NinoIntercepts</c>).</summary>
    public const string InterceptsAlias = "using __NinoIntercepts = " + TypeNames.CompilerServices +
                                          "InterceptsLocationAttribute;";

    /// <summary>
    /// A generated file: the <see cref="Header"/>, <paramref name="preamble"/> (what precedes the namespace, such as
    /// assembly attributes, as is), and the <c>NinoGen</c> namespace holding <paramref name="aliases"/> (declarations,
    /// one per line, then a blank line) and <paramref name="body"/> (written at no indentation, as a
    /// <see cref="CodeWriter"/> writes it). <paramref name="fileScoped"/>: the namespace is declared for the rest of
    /// the file (<c>namespace NinoGen;</c>, C# 10), where nothing follows the body and the preamble declares no
    /// namespace; otherwise it is a block, whose lines are indented one level.
    /// </summary>
    public static string File(string preamble, IEnumerable<string> aliases, string body, bool fileScoped)
    {
        var sb = new StringBuilder(Header, body.Length * (fileScoped ? 1 : 2) + preamble.Length + 1024);
        sb.Append(preamble);
        string indent = fileScoped ? "" : "    ";
        sb.Append(fileScoped ? "namespace " + TypeNames.GenNamespace + ";\n\n" : "namespace " + TypeNames.GenNamespace + "\n{\n");
        int length = sb.Length;
        foreach (var alias in aliases)
            sb.Append(indent).Append(alias).Append('\n');
        if (sb.Length != length)
            sb.Append('\n');
        if (fileScoped)
            return sb.Append(body).ToString();
        // The body's lines one level in (blank lines stay empty).
        int start = 0;
        while (start < body.Length)
        {
            int end = body.IndexOf('\n', start);
            end = end < 0 ? body.Length : end + 1;
            if (body[start] != '\n')
                sb.Append(indent);
            sb.Append(body, start, end - start);
            start = end;
        }

        sb.Append("}\n");
        return sb.ToString();
    }

    /// <summary>
    /// The names generated bodies repeat most, each with the alias <see cref="WithAliases"/> writes it as.
    /// A name ending in a dot is a static class, always followed by a member.
    /// </summary>
    private static readonly (string Name, string Alias)[] CoreAliases =
    {
        (TypeNames.Core + "Writer", "__NinoWriter"),
        (TypeNames.Core + "Reader", "__NinoReader"),
        (TypeNames.CoreCompilerServices + "NinoObject.", "__NinoObject."),
        (TypeNames.CoreCompilerServices + "NinoUnsafe.", "__NinoUnsafe."),
        (TypeNames.CoreCompilerServices + "NinoBlocks.", "__NinoBlocks."),
        (TypeNames.CoreCompilerServices + "NinoTypes.", "__NinoTypes."),
        ("global::System.ReadOnlySpan<byte>", "__NinoBytes"),
    };

    /// <summary>
    /// <paramref name="body"/> (the part of a file inside the <c>NinoGen</c> namespace) with the names it repeats
    /// written shorter. The generated types lose <c>global::NinoGen.</c>: the body is inside that namespace, whose own
    /// types a simple name finds before any other (only a type parameter of a generic formatter, which takes the names
    /// of its type's, or a nested type could hide one, and none is named like a generated type). Then the names
    /// become aliases: <paramref name="formatters"/> (generic formatters a type's members are read and written with,
    /// none naming a type parameter; numbered in their order) as <c>__NinoF0</c>, <c>__NinoF1</c>..., <paramref name="self"/> (a type the file is about, when
    /// given) as <c>__NinoT</c>, and the <see cref="CoreAliases"/>. A name is replaced only where the alias makes the
    /// file shorter, counting its declaration, which is added to <paramref name="declarations"/>; and only as a whole
    /// name: not next to an identifier character, a dot or a colon (a longer name, a qualified or nested one), but for
    /// the member that follows a static class's name.
    /// </summary>
    public static string WithAliases(string body, string? self, List<string> declarations,
        IEnumerable<string>? formatters = null)
    {
        body = body.Replace(TypeNames.Gen, "");
        var formatterAliases = new List<string>();
        if (formatters != null)
        {
            // Replaced longest first (a name inside a longer one is replaced with it), numbered in the order given
            // (the members').
            var names = formatters.Select(static n => n.Replace(TypeNames.Gen, "")).Distinct().ToList();
            var aliased = new List<string>();
            foreach (var name in names.OrderByDescending(static n => n.Length))
            {
                // Declared inside the namespace too, where the generated types need no qualifier either.
                int count = formatterAliases.Count;
                body = WithAlias(body, name, FormatterAlias(count), $"using {FormatterAlias(count)} = {name};",
                    formatterAliases);
                if (formatterAliases.Count != count)
                    aliased.Add(name);
            }

            // Renumbered from the order of replacement to the order given.
            var order = aliased.OrderBy(names.IndexOf).ToList();
            body = Regex.Replace(body, @"\b__NinoF(\d+)\b", x =>
                FormatterAlias(order.IndexOf(aliased[int.Parse(x.Groups[1].Value, CultureInfo.InvariantCulture)])));
            formatterAliases = order.Select((name, i) => $"using {FormatterAlias(i)} = {name};").ToList();
        }

        if (self != null)
            body = WithAlias(body, self, "__NinoT", $"using __NinoT = {self};", declarations);
        foreach (var (name, alias) in CoreAliases)
        {
            // A static class's alias is declared without the dot both names end with.
            string declaration = name[name.Length - 1] == '.'
                ? $"using {alias.Substring(0, alias.Length - 1)} = {name.Substring(0, name.Length - 1)};"
                : $"using {alias} = {name};";
            body = WithAlias(body, name, alias, declaration, declarations);
        }

        declarations.AddRange(formatterAliases);
        return body;
    }

    private static string FormatterAlias(int index) => "__NinoF" + index.ToString(CultureInfo.InvariantCulture);

    private static string WithAlias(string body, string name, string alias, string declaration,
        List<string> declarations)
    {
        // Count only until the alias pays for its declaration, including a line break and block-namespace indent.
        // Most candidates do not pay off, so leave their body alone without allocating a replacement buffer.
        int saving = name.Length - alias.Length;
        if (saving <= 0)
            return body;
        int needed = (declaration.Length + 5) / saving + 1;
        bool member = name[name.Length - 1] == '.';
        int first = FindName(body, name, 0, member);
        int at = first;
        for (int count = 1; at >= 0 && count < needed; count++)
            at = FindName(body, name, at + name.Length, member);
        if (at < 0)
            return body;

        var sb = new StringBuilder(body.Length);
        int start = 0;
        for (at = first; at >= 0; at = FindName(body, name, start, member))
        {
            sb.Append(body, start, at - start).Append(alias);
            start = at + name.Length;
        }

        sb.Append(body, start, body.Length - start);
        declarations.Add(declaration);
        return sb.ToString();
    }

    private static int FindName(string body, string name, int start, bool member)
    {
        int at;
        while ((at = body.IndexOf(name, start, StringComparison.Ordinal)) >= 0)
        {
            int end = at + name.Length;
            if ((at == 0 || !IsNamePart(body[at - 1])) && (member || end == body.Length || !IsNamePart(body[end])))
                return at;
            start = end;
        }

        return -1;
    }

    /// <summary>Whether <paramref name="c"/> next to a name makes it part of a longer one (qualified, nested).</summary>
    private static bool IsNamePart(char c) => char.IsLetterOrDigit(c) || c is '_' or '.' or ':';

    /// <summary>The name of the shared compile-time flags emitted with the assembly registry.</summary>
    public const string MethodFlags = "__NinoIL";

    /// <summary>The alias of <c>MethodImplAttribute</c> used by the generated methods.</summary>
    public static readonly string[] InlineAliases =
    {
        "using __NinoInline = " + TypeNames.CompilerServices + "MethodImplAttribute;",
    };

    /// <summary>The aggressive inlining attribute, through <see cref="InlineAliases"/>.</summary>
    public const string Inline = "[__NinoInline(" + MethodFlags + ".Inline)]";

    /// <summary>The no-inlining attribute, through <see cref="InlineAliases"/>.</summary>
    public const string NoInline = "[__NinoInline(" + MethodFlags + ".NoInline)]";
}
